-- VERIFY (read-only): expect 912 rows for this part.
SELECT c.table_name, c.change_type, c.field, count(*) AS n
FROM game_data_changes c JOIN game_patches p ON p.id = c.patch_id
WHERE p.game_slug = 'wardogs' AND p.patch_key = 'season-2' AND c.note = 'Evo4Fun workbook, sheet dated 30/10/2026, Season 2 per operator, not matched to a patch by the sheet itself'
  AND ((c.table_name = 'wardogs_ballistics' AND c.row_key->>'weapon_name' IN ('PKM', 'SKS', 'SVD', 'BMR-308', 'Scout Rifle TD', 'Mosin Nagant', 'SV98')))
GROUP BY c.table_name, c.change_type, c.field ORDER BY 1, 2, 3;
